            }
        },
    )

    adapter = LocalHostAdapter(tmp_path)
    minimal = adapter.next_step(identifier)
    assert minimal["current_action"]["record_refs"] == [
        "engineering.plan.implementation_slice:SLICE-001",
        "engineering.plan.verification_commands",
        "git",
